/**
 * RIOTOUS Brand Logo for Invoice PDF Generation
 *
 * High-contrast RGB image data (600x154) composited against solid dark charcoal (#111111)
 * with dedicated alpha soft-mask (/SMask) for crystal-clear logo visibility on dark containers.
 *
 * Sourced directly from public/assets/riotous-logo.png.
 */

export const RIOTOUS_LOGO_WIDTH = 600;
export const RIOTOUS_LOGO_HEIGHT = 154;
export const RIOTOUS_LOGO_ASPECT_RATIO = RIOTOUS_LOGO_WIDTH / RIOTOUS_LOGO_HEIGHT;

export const RIOTOUS_LOGO_DEFLATED_BASE64 =
  "";

export const RIOTOUS_LOGO_ALPHA_BASE64 =
  "";

let cachedLogoBytes: Uint8Array | null = null;
let cachedAlphaBytes: Uint8Array | null = null;

export function getRiotousLogoBytes(): Uint8Array {
  if (!cachedLogoBytes) {
    if (typeof Buffer !== "undefined") {
      cachedLogoBytes = new Uint8Array(Buffer.from(RIOTOUS_LOGO_DEFLATED_BASE64, "base64"));
    } else {
      const binaryString = atob(RIOTOUS_LOGO_DEFLATED_BASE64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      cachedLogoBytes = bytes;
    }
  }
  return cachedLogoBytes;
}

export function getRiotousLogoAlphaBytes(): Uint8Array {
  if (!cachedAlphaBytes) {
    if (typeof Buffer !== "undefined") {
      cachedAlphaBytes = new Uint8Array(Buffer.from(RIOTOUS_LOGO_ALPHA_BASE64, "base64"));
    } else {
      const binaryString = atob(RIOTOUS_LOGO_ALPHA_BASE64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      cachedAlphaBytes = bytes;
    }
  }
  return cachedAlphaBytes;
}
